const factsSummaryHandlers = {
  create_intake_notes: async (args) => {
    try {
      const case_uuid = args.case_uuid || args.matter_uuid;
      if (!case_uuid) throw new Error("Missing case_uuid.");

      const calculateAge = (dobString) => {
        if (!dobString) return "Unknown Age";
        const birthday = new Date(dobString);
        const ageDifMs = Date.now() - birthday.getTime();
        const ageDate = new Date(ageDifMs);
        return Math.abs(ageDate.getUTCFullYear() - 1970);
      };

      const prepareContext = (data, activeFields = [], excludeNoteIds = []) => {
        const cleanData = optimizeForVertex(data);
        const clientName = cleanData.client_full_name || "Unknown Client";
        const age = calculateAge(cleanData.date_of_birth);
        const county = cleanData.county_of_residence?.lookup_value_name || "Unknown County";
        const caseType = cleanData.legal_problem_code?.lookup_value_name || "General Legal Issue";
        
        let focusInstruction = "Focus on the chronological sequence of events.";
        for (const [key, instruction] of Object.entries(CASE_TYPE_FOCUS_MAP)) {
          if (caseType.includes(key) || (cleanData.legal_problem_category?.lookup_value_name || "").includes(key)) {
            focusInstruction = instruction;
            break;
          }
        }
      
        const incomeSummary = (cleanData.incomes || []).map(inc => 
          `- Type: ${inc.type?.lookup_value_name || 'Unknown'}, Amount: ${inc.amount}, Freq: ${inc.period}`
        ).join('\n');
      
        const apSummary = (cleanData.adverse_parties || []).map(ap => 
          `- Name: ${ap.first || ''} ${ap.last || ''} ${ap.organization_name || ''} (Rel: ${ap.relationship_type?.lookup_value_name || 'Unknown'})`
        ).join('\n');
      
        let householdSummary = (cleanData.non_adverse_parties || []).map(nap => {
          const napAge = nap.date_of_birth ? calculateAge(nap.date_of_birth) : "Unknown Age";
          return `- Name: ${nap.first || ''} ${nap.last || ''} (Age: ${napAge}) - Rel: ${nap.relationship_type?.lookup_value_name || 'Household Member'}`;
        }).join('\n');
        
        if (!householdSummary) {
          householdSummary = "WARNING: No structured data found. Extract child/household details from the Notes below.";
        }
      
        const intakeDetailSummary = activeFields.map(field => {
          const value = cleanData[field];
          if (value === undefined) return null;
          const label = field.replace(/_\d+$/, '').replace(/_/g, ' ');
          return `**${label}**: ${value}`;
        }).filter(item => item !== null).join('\n');
      
        const relevantNotes = (cleanData.notes || [])
          .filter(note => !excludeNoteIds.includes(note.id))
          .map(note => {
            const date = note.date_posted || "Unknown Date";
            const subject = note.subject ? `Subject: ${note.subject}` : "";
            const body = cleanText(note.body);
            return `[Note Date: ${date}] ${subject}\n${body}\n---`;
          })
          .join('\n');
      
        return {
          clientName, age, county, caseType, focusInstruction,
          incomeSummary, apSummary, householdSummary, intakeDetailSummary, relevantNotes
        };
      };

      const initialPath = `/api/v2/matters/${case_uuid}?results=full`;
      const initialRes = await callLegalserverAPI(initialPath);
      const baseData = initialRes.data?.[0] || initialRes.data || initialRes;
      const problemCode = baseData.legal_problem_code?.lookup_value_name || "";
      const codePrefix = problemCode.charAt(0);

      let finalData = baseData;
      let activeFields = PROBE_FIELD_MAP[codePrefix] || [];

      if (activeFields.length > 0) {
        const BATCH_SIZE = 150;
        const batches = [];
        for (let i = 0; i < activeFields.length; i += BATCH_SIZE) {
          batches.push(activeFields.slice(i, i + BATCH_SIZE));
        }

        console.log(`Matched prefix '${codePrefix}'. Batching ${activeFields.length} fields into ${batches.length} parallel calls...`);

        const probeResponses = await Promise.all(batches.map(async (batch) => {
          const queryString = batch.join('&');
          const batchPath = `/api/v2/matters/${case_uuid}?results=full&${queryString}`;
          const res = await callLegalserverAPI(batchPath);
          return res.data?.[0] || res.data || res;
        }));

        probeResponses.forEach(partData => {
          finalData = { ...finalData, ...partData };
        });
      }

      const context = prepareContext(finalData, activeFields, args.exclude_note_ids || []);

      return {
        success: true,
        system_prompt_addition: `
You are an expert Senior Paralegal. Review the following data and generate a "Summary of Legally Relevant Facts".

**YOUR INSTRUCTIONS:**
1. **Synthesize:** Combine structured data, custom intake fields (if present), and details found in the notes.
2. **Triangulate:** Find Adverse Party (AP) context in the notes.
3. **Find the Children:** If household summary says "WARNING", extract names/ages from notes or intake fields.
4. **Case Focus:** ${context.focusInstruction}
5. **Section I Tone (Critical):** Apply expert Senior Paralegal narrative tone ONLY to Section I (The Legal Narrative).
6. **Section I Do Not Dump Fields (Critical):** In Section I (The Legal Narrative), do NOT output a list of field labels (for example "Client Goal:", "AP Concerns:", "Custody History:"). Convert data into cohesive prose.
7. **Section I Format (Critical):** In Section I (The Legal Narrative), use 2-4 bold thematic subheaders (for example: "Custody and Children", "Domestic Violence and Safety Concerns", "Adverse Party Context"). Under each subheader, write a short synthesized paragraph.
8. **Sections II-VI Formatting:** For Sections II through VI, structured field-driven summaries and concise bullet formatting are acceptable.

**OUTPUT FORMAT (Markdown):**
# Summary of Legally Relevant Facts
**Client:** ${context.clientName} (${context.age}) | **County:** ${context.county}
**Case Type:** ${context.caseType}

## I. The Legal Narrative
(This is the primary section. Use bold thematic subheaders with paragraph-style narrative. Do NOT list raw field names.)

## II. Procedural Posture & Emergency
(Summarize current status and client goals. Use the 'deadlines' and 'priority' custom fields if available.)

## III. Financial & Household Snapshot
**Income/Benefits:**
${context.incomeSummary || "No income listed."}

**Household / Children:**
${context.householdSummary}

## IV. Detailed Intake Responses
${context.intakeDetailSummary || "No specialized intake responses were found for this case."}

## V. Adverse Parties
${context.apSummary || "No Adverse Parties listed."}

## VI. Missing Information / Action Items
(What documents or facts are missing?)
`,
        user_prompt_addition: `Here are the Raw Case Notes to analyze:\n\n${context.relevantNotes}`
      };
    } catch (error) {
      if (error.response) {
        console.error('LegalServer API Error: [REDACTED_PAYLOAD]');
        console.error('Attempted URL: [REDACTED_URL]');
      }
      throw error;
    }
  }
};

const factsSummarySchemas = [
  {
    name: "create_intake_notes",
    description: "Use ONLY when the user specifically asks for 'Intake Notes'. Do not use for general summaries.",
    parameters: {
      type: "OBJECT",
      properties: {
        case_uuid: { type: "STRING" },
        exclude_note_ids: { type: "ARRAY", items: { type: "INTEGER" } }
      },
      required: ["case_uuid"]
    }
  }
];

module.exports = { factsSummaryHandlers, factsSummarySchemas };
